-- Feature Documents are generated by the system, not requested by a user: the
-- sweep and the flow-analysis pipeline enqueue every job, and there is no UI that
-- asks a member to request one. feature_document_jobs.requested_by recorded
-- whichever account happened to be attached to the enqueue, which made the column
-- both meaningless and a RESTRICT foreign key blocking ordinary account deletion
-- (11,043 rows pointed at test accounts).
--
-- The store stopped reading and writing it already — JOB_COLUMNS, the job view
-- type, the INSERT and the row mapping in src/featureDocumentStore.ts no longer
-- mention it, and system-generated revisions record created_by = NULL.
ALTER TABLE feature_document_jobs DROP COLUMN IF EXISTS requested_by;
